{{ (() => {
  const j = $json;
  const clean = (s) => String(s ?? '')
    .replace(/\u0000/g, '')
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, ' ');
  const text = clean(j.extractedText);
  const b64 = Buffer.from(text, 'utf8').toString('base64');
  const esc = (s) => clean(s).replace(/'/g, "''");
  const has = (v) => v !== undefined && v !== null;
  const setExtra = [];
  if (has(j.ocrQualityScore)) setExtra.push(`ocr_quality_score = ${Number(j.ocrQualityScore)}`);
  if (has(j.ocrQualityGrade)) setExtra.push(`ocr_quality_grade = '${esc(j.ocrQualityGrade)}'`);
  if (has(j.ocrWordCount)) setExtra.push(`ocr_word_count = ${Number(j.ocrWordCount)}`);
  if (has(j.ocrUniqueWordCount)) setExtra.push(`ocr_unique_word_count = ${Number(j.ocrUniqueWordCount)}`);
  if (has(j.ocrCharacterCount)) setExtra.push(`ocr_character_count = ${Number(j.ocrCharacterCount)}`);
  if (has(j.ocrCharactersPerPage)) setExtra.push(`ocr_characters_per_page = ${Number(j.ocrCharactersPerPage)}`);
  if (has(j.ocrMode)) setExtra.push(`ocr_mode = '${esc(j.ocrMode)}'`);
  const extraSql = setExtra.length ? ',\n  ' + setExtra.join(',\n  ') : '';
  const vId = j.versionId || $('Buscar documento no PostgreSQL').first().json.versionId;
  return `UPDATE document_versions\nSET\n  extracted_text = convert_from(decode('${b64}', 'base64'), 'UTF8'),\n  processing_status = 'processed',\n  status = 'READY',\n  extraction_method = '${esc(j.extractionMethod || 'tika')}',\n  ocr_status = '${esc(j.ocrStatus || 'NOT_REQUIRED')}'${extraSql}\nWHERE id = '${esc(vId)}'::uuid\nRETURNING\n  id AS "versionId",\n  document_id AS id,\n  title_snapshot AS title,\n  processing_status AS "processingStatus",\n  LENGTH(extracted_text) AS "textLength";`;
})() }}
